#!/usr/bin/env node
// ASSEMBLY SEAL — is the tree about to be published the tree that was certified?
//
// The prose scan that decides what may leave does not live here and does not
// ship: its rule table names the things it exists to withhold, so a public copy
// of it would hand a reader the index to them. It runs one step earlier, on the
// private side, over this exact tree. This file asserts that nothing has moved
// since — which for a publish path is the stronger question, because a rule scan
// catches prose somebody wrote a rule for and this catches every edit.
//
// Generated by the assembly. Editing it changes nothing about what was certified.
//
// Exit 0 = the tree matches the seal.  Exit 1 = PUBLISH BLOCKED.

import { createHash } from "node:crypto";
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { dirname, join, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const SEAL = join(ROOT, "assembly-seal.json");

const SKIP_DIRS = new Set(["node_modules",".git","dist","coverage",".turbo",".next"]);
const SKIP_FILES = new Set(["assembly-seal.json"]);

function walk(dir, base, acc) {
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    if (SKIP_DIRS.has(e.name)) continue;
    const abs = join(dir, e.name);
    if (e.isDirectory()) walk(abs, base, acc);
    else {
      const rel = abs.slice(base.length + 1).split(sep).join("/");
      if (!SKIP_FILES.has(rel)) acc.push(rel);
    }
  }
  return acc;
}

const sha = (buf) => createHash("sha256").update(buf).digest("hex");

if (!existsSync(SEAL)) {
  console.error("REFUSING - assembly-seal.json is absent, so there is nothing to check this");
  console.error("tree against. Publish from an assembled tree, never from a hand-made one.");
  process.exit(1);
}
const seal = JSON.parse(readFileSync(SEAL, "utf8"));
const sealed = seal.files || {};
const sealedPaths = Object.keys(sealed);

// A SEAL OVER NOTHING ALWAYS PASSES.
if (sealedPaths.length === 0) {
  console.error("REFUSING - the seal lists no files, so it certifies nothing.");
  process.exit(1);
}

const findings = [];
for (const rel of sealedPaths) {
  const abs = join(ROOT, rel);
  if (!existsSync(abs)) findings.push("MISSING   " + rel);
  else if (sha(readFileSync(abs)) !== sealed[rel]) findings.push("MODIFIED  " + rel);
}
const present = walk(ROOT, ROOT, []).sort();
for (const rel of present) if (!(rel in sealed)) findings.push("UNSEALED  " + rel);

// And the seal cannot vouch for itself by being rewritten.
const recomputed = sha(sealedPaths.slice().sort().map((p) => p + "\u0000" + sealed[p]).join("\n"));
if (recomputed !== seal.digest) findings.push("THE SEAL DOES NOT MATCH ITS OWN DIGEST");

console.log("assembly seal - " + sealedPaths.length + " sealed, " + present.length + " present");
if (findings.length) {
  console.error("");
  console.error("PUBLISH BLOCKED - " + findings.length + " difference(s) from the certified tree:");
  for (const f of findings) console.error("  " + f);
  console.error("");
  console.error("Anything edited here was never read by the scan that decides what may leave,");
  console.error("so this path refuses rather than publish bytes nobody checked. Re-assemble.");
  process.exit(1);
}
console.log("  sealed - every file matches the tree the assembly certified");
